// 打ったキーフレームのあいだをカーブで埋めて補間する — この記事の動きはぜんぶこの形で書ける
function keyAt(keys, frame) {
  if (frame <= keys[0].frame) return keys[0].value;          // 最初のキー以前 — 最初の値のまま
  if (frame > keys.at(-1).frame) return keys.at(-1).value;   // 終わりより後 — 最後の値のまま
  const next = keys.findIndex((key) => frame <= key.frame);  // いま向かっている先のキーの番号
  const a = keys[next - 1], b = keys[next];                  // 手前のキーとの 2 個で区間が決まる
  const t = (frame - a.frame) / (b.frame - a.frame);         // 区間の進み具合 0〜1
  return a.value + (b.value - a.value) * a.curve(t);         // 差をカーブの形で進める
}

// 動かしているのは呼吸 1 本。半径も回転も出現も、打ったキーフレームのあいだを keyAt で補間するだけ。
// 小文字ではじまる裸の名前(holdStart や radiusRest)は、自分の画面に合わせて決める数 —
// この記事が持ち帰ってほしいのは値ではなく、この「形」だ。
const linear = (t) => t; // 値が同じ区間用 — どんなカーブでも動かない

// カーブは全部 CSS の cubic-bezier() と同じ規格 — 置く数は好みで決める
const breathOpen  = cubicBezier(...breathOpenHandles);  // 呼吸の開き
const breathClose = cubicBezier(...breathCloseHandles); // 呼吸の閉じ — 開きと別の顔
const spinRise    = cubicBezier(...spinRiseHandles);    // 回転の行き
const spinFall    = cubicBezier(...spinFallHandles);    // 回転の帰り
const railOut     = cubicBezier(...railOutHandles);     // 外縁レールの行き
const railBack    = cubicBezier(...railBackHandles);    // 外縁レールの帰り

// 呼吸 — 開きと閉じで別カーブ、値が同じ区間は保ちになる
const breathKeys = [
  { frame: openStart, value: 0, curve: breathOpen },  // ここから開きはじめる
  { frame: holdStart, value: 1, curve: linear },      // 開き切る — ここから保ち
  { frame: holdEnd,   value: 1, curve: breathClose }, // 保ちおわり — 閉じへ
  { frame: closeEnd,  value: 0 },                     // 閉じ切って静止
];
// 回転 — フレーム区間は呼吸と同じ、カーブだけ自分の 2 本を持つ
const spinKeys = [
  { frame: openStart, value: 0,     curve: spinRise },
  { frame: holdStart, value: 1 / 2, curve: linear },  // 保ちまでに半分回る
  { frame: holdEnd,   value: 1 / 2, curve: spinFall },
  { frame: closeEnd,  value: 1 },                     // 残り半分は帰り道で
];
// 外縁専用レール — 半径の往復を自分のフレーム区間で持つ
const railKeys = [
  { frame: railStart,     value: railRest, curve: railOut },
  { frame: railHoldStart, value: railPeak, curve: linear },
  { frame: railHoldEnd,   value: railPeak, curve: railBack },
  { frame: railEnd,       value: railRest },
];

const center = { x: stageSize / 2, y: stageSize / 2 }; // 一辺 stageSize のキャンバスの中心
const rad = (deg) => (deg * Math.PI) / 180; // 度 → ラジアン

// フレーム番号を渡すと 19 個ぶんの位置と大きさを返す関数
function latticeAt(frame) {
  const breath = keyAt(breathKeys, frame);
  const radius = radiusRest + (radiusPeak - radiusRest) * breath; // 半径だけが呼吸に乗る
  const spin = spinPerLoop * keyAt(spinKeys, frame);
  return dots.map((dot) => ({
    angle: dot.angle + spin,                           // 全ドットが同じ回転に乗る
    dist: dot.role === "arm"  ? radius                 // 土台 — 呼吸の半径
        : dot.role === "edge" ? keyAt(railKeys, frame) // 外縁 — 専用レール
        : dot.dist,                                    // 中心と内側の輪 — 行の距離のまま
    scale: dot.grow ? keyAt(dot.grow, frame) : 1,      // 出現も退場も scale のキー
  }));
}

// 角度と距離から画面の座標へ
function dotXY(dot) {
  return {
    x: center.x + dot.dist * Math.cos(rad(dot.angle)),
    y: center.y - dot.dist * Math.sin(rad(dot.angle)), // 画面の y 軸は下向きなので −sin
  };
}

// 打ったキーフレームのあいだをカーブで埋めて補間する — この記事の動きはぜんぶこの形で書ける
function keyAt(keys, frame) {
  if (frame <= keys[0].frame) return keys[0].value;          // 最初のキー以前 — 最初の値のまま
  if (frame > keys.at(-1).frame) return keys.at(-1).value;   // 終わりより後 — 最後の値のまま
  const next = keys.findIndex((key) => frame <= key.frame);  // いま向かっている先のキーの番号
  const a = keys[next - 1], b = keys[next];                  // 手前のキーとの 2 個で区間が決まる
  const t = (frame - a.frame) / (b.frame - a.frame);         // 区間の進み具合 0〜1
  return a.value + (b.value - a.value) * a.curve(t);         // 差をカーブの形で進める
}

// 動きの部品はクリップ 1 本と、順番を書き込んだ表 1 枚だけ。
// 小文字ではじまる裸の名前(clipStart や restRadius)は、自分の画面に合わせて決める数 —
// この記事が持ち帰ってほしいのは値ではなく、この「形」だ。
const linear = (t) => t; // 値が同じ区間用 — 保ちはこれで出る

// 区間ごとのカーブ — どれも CSS の cubic-bezier() と同じ規格。好みの 4 つの数で決める
const popEase = cubicBezier(...popHandles);         // 静止 → 頂点
const dropEase = cubicBezier(...dropHandles);       // 頂点 → 落としすぎ
const recoverEase = cubicBezier(...recoverHandles); // 落としすぎ → 拾い
const settleEase = cubicBezier(...settleHandles);   // 保ちおわり → 静止

const clipKeys = [ // 値 = 半径。各キーフレームのカーブは「次のキーへ向かう区間」のもの
  { frame: 0,          value: restRadius,  curve: popEase },     // → 弾む
  { frame: peakFrame,  value: peakRadius,  curve: dropEase },    // → 落としすぎる
  { frame: underFrame, value: underRadius, curve: recoverEase }, // → 拾う
  { frame: holdStart,  value: holdRadius,  curve: linear },      // → そのまま保つ
  { frame: holdEnd,    value: holdRadius,  curve: settleEase },  // → 静止へ戻る
  { frame: clipEnd,    value: restRadius },
];

// 「ランダム」の正体はこの表 1 枚 — 9 マスに何番目かを 1 回ずつ書き込んだ固定の順番表。
// fireOrder は乱数を使わず、自分で 1 度だけスクランブルして書く

// フレーム番号を渡すと 9 個の半径を返す関数 — 再生側は frame を loopFrames(ループ 1 周)で割った余りにする
function radiiAt(frame) {
  return fireOrder.flat().map((rank) => {
    const local = frame - clipStart - rank * stepFrames; // 自分の番のぶん遅れて再生
    return keyAt(clipKeys, local);                       // キーの間を区間カーブで埋める
  });
}

// 打ったキーフレームのあいだをカーブで埋めて補間する — この記事の動きはぜんぶこの形で書ける
function keyAt(keys, frame) {
  if (frame <= keys[0].frame) return keys[0].value;          // 最初のキー以前 — 最初の値のまま
  if (frame > keys.at(-1).frame) return keys.at(-1).value;   // 終わりより後 — 最後の値のまま
  const next = keys.findIndex((key) => frame <= key.frame);  // いま向かっている先のキーの番号
  const a = keys[next - 1], b = keys[next];                  // 手前のキーとの 2 個で区間が決まる
  const t = (frame - a.frame) / (b.frame - a.frame);         // 区間の進み具合 0〜1
  return a.value + (b.value - a.value) * a.curve(t);         // 差をカーブの形で進める
}

// 動かしているのは中央の回転 1 本。両脇はそれを接触の法則で読むだけ。
// 小文字ではじまる裸の名前(riseStart や side)は、自分の画面に合わせて決める数 —
// この記事が持ち帰ってほしいのは値ではなく、この「形」だ。
const climbCurve = cubicBezier(...climbHandles);     // CSS の cubic-bezier() と同じ規格 — 緩急は好みの 4 つの数で
const descendCurve = cubicBezier(...descendHandles); // 帰り区間用 — 同じ規格でもう 1 本

// 回転に打つキーフレーム: 直立 → ダイヤ → 四分の一回転で直立に戻る。打ってあるのはこれだけ
const rotationKeys = [
  { frame: riseStart,    value: 0,            curve: climbCurve },   // → ダイヤへ上る
  { frame: diamondFrame, value: diamondAngle, curve: descendCurve }, // → 直立へ下りる
  { frame: loopEnd,      value: quarterTurn },
];

// フレーム番号を渡すと、中央の角度と両脇の位置を返す関数
function squaresAt(frame) {
  const angle = keyAt(rotationKeys, frame);
  // 法則 1 行: 回転した正方形の横幅の半分は「ダイヤからの離れ具合」で決まる
  const phi = Math.abs(((angle % quarterTurn) + quarterTurn) % quarterTurn - diamondAngle);
  const halfWidth = (side / Math.SQRT2) * Math.cos((phi * Math.PI) / 180);
  const push = Math.max(0, halfWidth - side / 2 - gap); // 隙間 gap を保って押し出す
  return {
    center: { rotate: angle },
    left:   { x: leftHome - push },  // 両脇にキーはゼロ — 法則は左右対称
    right:  { x: rightHome + push },
  };
}

// 打ったキーフレームのあいだをカーブで埋めて補間する — この記事の動きはぜんぶこの形で書ける
function keyAt(keys, frame) {
  if (frame <= keys[0].frame) return keys[0].value;          // 最初のキー以前 — 最初の値のまま
  if (frame > keys.at(-1).frame) return keys.at(-1).value;   // 終わりより後 — 最後の値のまま
  const next = keys.findIndex((key) => frame <= key.frame);  // いま向かっている先のキーの番号
  const a = keys[next - 1], b = keys[next];                  // 手前のキーとの 2 個で区間が決まる
  const t = (frame - a.frame) / (b.frame - a.frame);         // 区間の進み具合 0〜1
  return a.value + (b.value - a.value) * a.curve(t);         // 差をカーブの形で進める
}

// 打ってあるのは左上の半径 1 本。右下は引き算で、中心 2 つは接点からの計算で決まる。
// 小文字ではじまる裸の名前(restRadius や contact)は、自分の画面に合わせて決める数 —
// この記事が持ち帰ってほしいのは値ではなく、この「形」だ。
const shrink = cubicBezier(...shrinkHandles); // CSS の cubic-bezier() と同じ規格 — しぼみ区間のカーブ
const grow = cubicBezier(...growHandles);     // ふくらみ区間のカーブ — 似ているが別の 1 本

// 半径に打つキーフレーム: 値 = 左上の半径。打ってあるのはここだけで、どのフレームに打つかは自分で決める
const radiusKeys = [
  { frame: 0,          value: restRadius, curve: shrink }, // → しぼむ
  { frame: midFrame,   value: midRadius,  curve: grow },   // → ふくらむ — 折り返し
  { frame: loopFrames, value: restRadius },                // 戻り切って静止 — ループの継ぎ目
];

// フレーム番号を渡すと 2 円の中心と半径を返す関数
function circlesAt(frame) {
  const r1 = keyAt(radiusKeys, frame);      // 左上の半径
  const r2 = radiusSum - r1;                // 右下はキーゼロ — 引き算 1 行
  const d = Math.SQRT1_2;                   // 対角線の向きの成分(= 1 / √2)
  return [
    { r: r1, x: contact - r1 * d, y: contact - r1 * d }, // 接点から左上へ退く
    { r: r2, x: contact + r2 * d, y: contact + r2 * d }, // 接点から右下へ退く
  ];
}

// 動かしているのは回転 1 本。残りは全部、その読み替え。
// 小文字ではじまる裸の名前(copies や delayFrames)は、自分の画面に合わせて決める数 —
// この記事が持ち帰ってほしいのは値ではなく、この「形」だ。
const ease = cubicBezier(...easeHandles); // CSS の cubic-bezier() と同じ規格 — 緩急は好みの数で
const rad = (deg) => (deg / 360) * 2 * Math.PI; // 度をラジアンに直す

// 置き場所も自分で決める数 — 軌道の中心(center)・軌道の半径(orbitRadius)・ドットの半径(dotRadius)。
// restAngles には、正反対の 2 個ぶんの静止角を並べる

// フレーム番号を渡すと、描く円の一覧を返す関数（loopFrames フレームでループ）
function dotsAt(frame) {
  return restAngles.flatMap((rest) =>
    Array.from({ length: copies + 1 }, (_, copy) => {       // 0 = 本体、あとは複製
      const past = frame - copy * delayFrames;              // 複製は少しだけ過去を読む
      const t = Math.min(Math.max(past / sweepFrames, 0), 1); // 進み具合を 0〜1 に直す
      return {
        angle: rest + 360 * ease(t),                        // 1 周ぶん回す
        opacity: fadePerCopy ** copy,                       // 1 枚ごとに fadePerCopy 倍薄く
      };
    })
  );
}

// 動かしているのはパルス 1 本。図形はみんな、それを自分の動き幅で読むだけ。
// 小文字ではじまる裸の名前(riseStart や barW)は、自分の画面に合わせて決める数 —
// この記事が持ち帰ってほしいのは値ではなく、この「形」だ。
const ease = cubicBezier(...easeHandles); // CSS の cubic-bezier() と同じ規格 — 緩急は好みの 4 つの数で

// パルスに打つキーフレーム: 0 → 1 → (1 のまま) → 0。間は ease で埋める
const pulseKeys = [
  { frame: riseStart, value: 0, curve: ease }, // ここから伸びはじめる
  { frame: holdStart, value: 1, curve: ease }, // 伸び切る — ここから「ため」
  { frame: holdEnd,   value: 1, curve: ease }, // ためおわり — 同じカーブのまま下りになる
  { frame: loopEnd,   value: 0, curve: ease }, // 戻り切って静止
];

// 打ったキーフレームのあいだをカーブで埋めて補間する — この記事の動きはぜんぶこの形で書ける
function keyAt(keys, frame) {
  if (frame <= keys[0].frame) return keys[0].value;          // 最初のキー以前 — 最初の値のまま
  if (frame > keys.at(-1).frame) return keys.at(-1).value;   // 終わりより後 — 最後の値のまま
  const next = keys.findIndex((key) => frame <= key.frame);  // いま向かっている先のキーの番号
  const a = keys[next - 1], b = keys[next];                  // 手前のキーとの 2 個で区間が決まる
  const t = (frame - a.frame) / (b.frame - a.frame);         // 区間の進み具合 0〜1
  return a.value + (b.value - a.value) * a.curve(t);         // 差をカーブの形で進める
}

// 図形ごとの動き幅: 置き場所と「パルス 1 につきどれだけ動くか」。
// 外側のバーほど大きく、左右では slide の符号だけが逆 — 鏡写しの正体はこの符号
const shapes = [
  { x: outerLeftX,  w: barW,    h: barH,    growW: 0,          growH: outerGrow,  slide: -outerSlide, spin: 0        },
  { x: innerLeftX,  w: barW,    h: barH,    growW: 0,          growH: innerGrow,  slide: -innerSlide, spin: 0        },
  { x: centerX,     w: squareW, h: squareH, growW: squareGrow, growH: squareGrow, slide: 0,           spin: halfTurn },
  { x: innerRightX, w: barW,    h: barH,    growW: 0,          growH: innerGrow,  slide: innerSlide,  spin: 0        },
  { x: outerRightX, w: barW,    h: barH,    growW: 0,          growH: outerGrow,  slide: outerSlide,  spin: 0        },
];

// フレーム番号を渡すと、図形の置き方の一覧を返す関数(loopFrames ごとにループ)
function shapesAt(frame) {
  const pulse = keyAt(pulseKeys, frame % loopFrames);
  return shapes.map((s) => ({
    cx: s.x + s.slide * pulse,            // 横の置き場所 — 左は引かれ、右は足される
    cy: stageSize / 2,                    // 縦は固定 — 画面の中心の高さ
    width:  s.w + s.growW * pulse,
    height: s.h + s.growH * pulse,
    angle:  s.spin * pulse,               // 中央だけ halfTurn(半回転)まで回る
  }));
}

// 動かすのは「頭の進み具合」u 1 本。0 が道の出発点、1 でちょうど 1 周。
// 小文字ではじまる裸の名前(whipSpan や periodFrames)は、自分の画面に合わせて決める数 —
// この記事が持ち帰ってほしいのは値ではなく、この「形」だ。
const whip = cubicBezier(...whipHandles); // CSS の cubic-bezier() と同じ規格 — 鞭の顔は好みの 4 つの数で
const linear = (t) => t;                  // 這いはまっすぐ進むだけ

// 這いは余り — 自分では決められない
const crawlSpan = 1 - whipSpan;                      // 這いが受け持つ残りの割合
const crawlDurFrames = periodFrames - whipDurFrames; // 這いに残るフレーム数

// 画面に映すほうのつまみ: stageSize 四方のキャンバス・幅 strokeWidth の線・半径 dotRadius のドット。
// paintHeadLag は切れ目がドットの前後にまたがるよう目で合わせるずらし
const gapFraction = 1 - drawnFraction; // 窓が描く割合 drawnFraction の残りが切れ目

// u に打つキーフレーム: 鞭が whipSpan を食べ、残りは「1 周して戻る」ための直線
const uKeys = [
  { frame: 0,             value: uAtWhipStart,            curve: whip   }, // 鞭の始まり = 出発位置
  { frame: whipDurFrames, value: uAtWhipStart + whipSpan, curve: linear }, // 鞭の終わり
  { frame: periodFrames,  value: uAtWhipStart + 1 },                       // 1 周して同じ場所 — ここは選べない
];

// 打ったキーフレームのあいだをカーブで埋めて補間する — この記事の動きはぜんぶこの形で書ける
function keyAt(keys, frame) {
  if (frame <= keys[0].frame) return keys[0].value;          // 最初のキー以前 — 最初の値のまま
  if (frame > keys.at(-1).frame) return keys.at(-1).value;   // 終わりより後 — 最後の値のまま
  const next = keys.findIndex((key) => frame <= key.frame);  // いま向かっている先のキーの番号
  const a = keys[next - 1], b = keys[next];                  // 手前のキーとの 2 個で区間が決まる
  const t = (frame - a.frame) / (b.frame - a.frame);         // 区間の進み具合 0〜1
  return a.value + (b.value - a.value) * a.curve(t);         // 差をカーブの形で進める
}

// フレーム番号 → 頭の進み具合。鞭の開始 whipStartFrame を 0 に合わせてから、打ってあるキーフレームのあいだを補間する
function uAt(frame) {
  const local = ((frame - whipStartFrame) % periodFrames + periodFrames) % periodFrames;
  return keyAt(uKeys, local) % 1; // 1 を超えたぶんは次の周回へ巻き戻す
}

// 動かしている数値は「進み具合」u の 1 本だけ — 0 で静止、1 で離れ切り、2 でまた閉じる。
// 小文字ではじまる裸の名前(splitStart や slideMax)は、自分の画面に合わせて決める数 —
// この記事が持ち帰ってほしいのは値ではなく、この「形」だ。
const openCurve = cubicBezier(...openHandles);   // 割れて離れるビートの緩急 — CSS の cubic-bezier() と同じ規格
const closeCurve = cubicBezier(...closeHandles); // 閉じて戻るビートの緩急

// u に打つキーフレーム: 0 → 1 → 2。値 1 までが行き、2 までが帰り。各キーフレームの curve は次のキーフレームまでの区間に効く
const uKeys = [
  { frame: splitStart, value: 0, curve: openCurve },  // ここまで円のまま静止
  { frame: apartPeak,  value: 1, curve: closeCurve }, // 離れ切る — 回転はまだ道半ば
  { frame: sealEnd,    value: 2, curve: closeCurve }, // 閉じ切る — 残りは静止
];

// 打ったキーフレームのあいだをカーブで埋めて補間する — この記事の動きはぜんぶこの形で書ける
function keyAt(keys, frame) {
  if (frame <= keys[0].frame) return keys[0].value;          // 最初のキー以前 — 最初の値のまま
  if (frame > keys.at(-1).frame) return keys.at(-1).value;   // 終わりより後 — 最後の値のまま
  const next = keys.findIndex((key) => frame <= key.frame);  // いま向かっている先のキーの番号
  const a = keys[next - 1], b = keys[next];                  // 手前のキーとの 2 個で区間が決まる
  const t = (frame - a.frame) / (b.frame - a.frame);         // 区間の進み具合 0〜1
  return a.value + (b.value - a.value) * a.curve(t);         // 差をカーブの形で進める
}

// フレーム番号を渡すと、2 つの半円の置き場所を返す関数(loopFrames ごとにループ)
function piecesAt(frame) {
  const u = keyAt(uKeys, frame % loopFrames);
  const turn = (turnPerLoop * u) / 2;             // 回転は u に比例 — 自前の緩急を持たず、戻りもしない
  const slide = slideMax * (1 - Math.abs(1 - u)); // すれ違いは山なり — 行って帰る
  const inset = Math.min(slide, seamInset);       // 相手側への押し込み — すぐ頭打ちになる

  // 切り口の向き cutAngle(縦なら 90)に沿ってすれ違い、直角の向きに押し込む
  const cut = (cutAngle * Math.PI) / 180;
  const alongX = Math.cos(cut);                   // 切り口に沿う向き
  const alongY = Math.sin(cut);
  const intoX = alongY;                           // 半円 A が相手へめり込む向き
  const intoY = -alongX;

  // 半円 A のずれを作り、グループ回転で回してから中心に足す
  const shiftX = intoX * inset - alongX * slide;
  const shiftY = intoY * inset - alongY * slide;
  const g = (turn * Math.PI) / 180;
  const ax = centerX + Math.cos(g) * shiftX - Math.sin(g) * shiftY;
  const ay = centerY + Math.sin(g) * shiftX + Math.cos(g) * shiftY;

  // ふくらむ向き = 切り口と直角 + グループ回転ぶん。半円 B は A の点対称
  const bulgeA = cutAngle + 90 + turn;
  return [
    { x: ax, y: ay, r: discRadius, bulge: bulgeA },
    { x: 2 * centerX - ax, y: 2 * centerY - ay, r: discRadius, bulge: bulgeA + 180 },
  ];
}

// 芯は「集まる → 待つ → もどる」のクリップ 1 本 — 8 個の円は止まらない輪に乗って、同じクリップを遅らせ再生する。
// 小文字ではじまる裸の名前(gatherSpan や ringRadius)は、自分の画面に合わせて決める数 —
// この記事が持ち帰ってほしいのは値ではなく、この「形」だ。
const easeIn = (t) => t * t * t; // 集まりの緩急 — そっと離れて、中心へ加速着地
const easeOutBack = (t) => {
  // もどりの緩急 — 定位置を少し行き過ぎてから落ち着く。行き過ぎ量は backOvershoot
  const u = t - 1;
  return 1 + (backOvershoot + 1) * u * u * u + backOvershoot * u * u;
};

// クリップ本体: 進み具合を返す。0 が輪の上の定位置、1 が中心。loopFrames ごとに繰り返す
function progressAt(frame) {
  const t = ((frame % loopFrames) + loopFrames) % loopFrames; // マイナスのフレームでも 0〜loopFrames に巻き戻す(遅らせ再生は頭より前を読むことがある)
  if (t < gatherSpan) return easeIn(t / gatherSpan); // 集まる
  if (t < gatherSpan + holdSpan) return 1; // 中心で待つ
  if (t < gatherSpan + holdSpan + backSpan)
    return 1 - easeOutBack((t - gatherSpan - holdSpan) / backSpan); // もどる
  return 0; // 輪の上で待機
}

// なだらかな S 字で 0→1 を渡る(いわゆる smoothstep)
const smooth = (s) => {
  const u = Math.min(1, Math.max(0, s));
  return u * u * (1 + 2 - 2 * u);
};

// 呑み込まれ具合: 中心に着いてから absorbWindow のあいだで 1 へ、離れはじめたら同じ長さで 0 へ
function absorbAt(frame) {
  const t = ((frame % loopFrames) + loopFrames) % loopFrames;
  return smooth((t - gatherSpan) / absorbWindow) * (1 - smooth((t - gatherSpan - holdSpan) / absorbWindow));
}

// フレーム番号を渡すと、まん中の円と 8 個の円の置き場所を返す関数
function blobsAt(frame) {
  // まわる輪: 等間隔に置き、毎フレーム turnPerFrame ぶんの回転を足しつづける
  const ring = Array.from({ length: copyCount }, (_, i) => {
    const a = ((ringStart + turnPerFrame * frame + (360 / copyCount) * i) * Math.PI) / 180;
    return { x: centerX + ringRadius * Math.cos(a), y: centerY + ringRadius * Math.sin(a) };
  });

  // ずらし再生: i 番目はおなじクリップを staggerStep × i フレーム遅れで読む
  const localFrames = ring.map((_, i) => frame + clipShift - i * staggerStep);

  // 各円: 輪の上の定位置から中心へ、進み具合のぶんだけ寄せる
  const dots = ring.map((pt, i) => {
    const p = progressAt(localFrames[i]);
    return { x: pt.x + (centerX - pt.x) * p, y: pt.y + (centerY - pt.y) * p, r: dotRadius };
  });

  // まん中の円: 呑み込まれ具合の平均の平方根を満杯半径に掛ける(面積は呑んだ個数に比例)
  const share = localFrames.map((f) => absorbAt(f)).reduce((sum, a) => sum + a, 0) / copyCount;
  const coreR = coreFullRadius * Math.sqrt(share);
  const core = coreR > minVisibleRadius ? { x: centerX, y: centerY, r: coreR } : null;
  return { core, dots };
}

// 動かしているのはキー移動 1 本と、その勢いで出る揺れ。残りは全部その読み替え。
// 小文字ではじまる裸の名前(loopFrames や settleRate)は、自分の画面に合わせて決める数 —
// この記事が持ち帰ってほしいのは値ではなく、この「形」だ。

const wrap = (value, span) => ((value % span) + span) % span;

const exitSpeed = (move) => {
  const keys = move.keys;
  const last = keys[keys.length - 1];
  const prev = keys[keys.length - 2];
  const [, , handleX, handleY] = move.eases[move.eases.length - 1]; // 最終区間の緩急を決める数
  const slope = (1 - handleY) / (1 - handleX); // キーを離れる瞬間の傾き
  return (slope * (last.x - prev.x)) / (last.t - prev.t);
};

const keyedLeg = (tau, move) => { // 片道のキー移動。時刻 tau がどの区間にいるかを探し、その区間の緩急で位置を返す
  const keys = move.keys;
  if (tau < keys[0].t) return keys[0].x; // 動きはじめる前 — 出発点で待つ
  const seg = keys.findIndex((k, i) => i > 0 && tau < k.t); // tau を追い越す最初のキー
  if (seg < 0) return keys[keys.length - 1].x; // 動き終わったあと — 到着点で待つ
  const from = keys[seg - 1];
  const to = keys[seg];
  const ease = cubicBezier(...move.eases[seg - 1]);
  return from.x + (to.x - from.x) * ease((tau - from.t) / (to.t - from.t));
};

function channelAt(frame, move) { // 1 本のチャンネルの位置: 片道の振り + 振り抜く速さで出る揺れ。loopFrames ごとに繰り返す
  const half = loopFrames / 2;
  const t = wrap(frame, loopFrames);
  const restA = move.keys[0].x;
  const restB = move.keys[move.keys.length - 1].x;
  const endTime = move.keys[move.keys.length - 1].t;
  const keyed = t < half ? keyedLeg(t, move) : restA + restB - keyedLeg(t - half, move); // 後半は前半を左右反転して再生 — 片道だけ author すれば 1 周が閉じる
  const speed = exitSpeed(move);
  // 揺れ: 行って戻るサインがだんだん小さくなりながら収まる。大きさは振り抜く速さで決まる
  // 両端の到着ぶんを足す(後半は符号を反転)。1 周ぶん前まで読んで前周の残りも拾う
  const arrivals = [[endTime, 1], [endTime + half, -1]];
  return arrivals.flatMap(([arrival, sign]) =>
    [0, 1].map((lap) => {
      const d = wrap(t - arrival, loopFrames) + lap * loopFrames;
      return sign * ((speed * Math.exp(-move.settleDecay * d) * Math.sin(move.settleRate * d)) / move.settleRate);
    })
  ).reduce((sum, ring) => sum + ring, keyed);
}

function glyphAt(frame) { // フレーム番号を渡すと、茎の両端と点の置き場所を返す。3 本のチャンネルがそれぞれ x を動かす
  return {
    stemTop: { x: channelAt(frame, topMove), y: capTopY },
    stemBot: { x: channelAt(frame, botMove), y: capBotY },
    stemWidth,
    dot: { cx: channelAt(frame, dotMove), cy: dotCy, r: dotRadius },
  };
}

// 動かしているのは上下の波 1 本だけ。7 つの円はそれぞれの振れ幅でその波を読む。
// 小文字ではじまる裸の名前(periodFrames や bottomKeyFrame)は、自分の画面に
// 合わせて決める数 — この記事が持ち帰ってほしいのは値ではなく、この「形」だ。

const wrap = (value, span) => ((value % span) + span) % span;

const sharedWave = (designTime) => { // 上 → 下 → 上 を行き来する波。下りと上りで別のカーブ
  const descEase = cubicBezier(...descHandles); // 下り(上→下)の緩急
  const ascEase = cubicBezier(...ascHandles);   // 上り(下→上)の緩急
  const t = wrap(designTime, periodFrames);
  if (t <= bottomKeyFrame) return -1 + 2 * descEase(t / bottomKeyFrame); // 上から下へ
  return 1 - 2 * ascEase((t - bottomKeyFrame) / (periodFrames - bottomKeyFrame)); // 下から上へ
};

function dotsAt(frame) { // フレーム番号 → 7 つの円の置き場所。波を計算し、円ごとに振れ幅で読む
  const wave = sharedWave(frame + capturePhase);
  return circles.map((c) => ({
    cx: c.cx,
    cy: c.mid + c.amp * wave,
    r: c.r,
  }));
}

const deg = Math.PI / 180;
const signedArc = (from, to) => ((to - from + 180) % 360 + 360) % 360 - 180;

// 2 つの配置から、各点の位置を先に割り出す
const restRadius = restPositions.map(([x, y]) => Math.hypot(x - cx, y - cy));
const restAngle = restPositions.map(([x, y]) => Math.atan2(y - cy, x - cx) / deg);
const slotAngle = restToRing.map((slot) => ringAnglesDeg[slot]);
const angleGap = restAngle.map((a, dot) => signedArc(a, slotAngle[dot]));
const slotPoint = ringAnglesDeg.map((a) => [
  cx + ringRadius * Math.cos(a * deg),
  cy + ringRadius * Math.sin(a * deg),
]);
const back = -turntableDeg * deg;
const destLocal = restToRing.map((slot, dot) => {
  if (dot === centerDestinationDot) return [0, 0]; // 行き先が中心の点はそこを狙う
  const [x, y] = restPositions[ringToRest[slot]];
  const lx = x - cx;
  const ly = y - cy;
  return [lx * Math.cos(back) - ly * Math.sin(back), lx * Math.sin(back) + ly * Math.cos(back)];
});

const wrap = (frame, span) => ((frame % span) + span) % span;
const [lobeIn, lobeOut] = lobeXHandles;
const swingEase = cubicBezier(lobeIn, 0, lobeOut, 1);
const lastArrival = Math.max(...arrivals);

// 最初の動き: いちど中央へ引きこんでから外のスロットへ放る(共有のふくらみ)
const expand = (frame, dot) => {
  const span =
    frame <= departures[dot] ? 0 : frame >= arrivals[dot] ? 1 : (frame - departures[dot]) / (arrivals[dot] - departures[dot]);
  if (dot === centerSeatDot) { // 休み席が中心の点はへこむ余地がない → 半径は素直に外へ
    const radius = restRadius[dot] + swingEase(span) * (ringRadius - restRadius[dot]);
    const angle = slotAngle[dot] * deg;
    return [cx + radius * Math.cos(angle), cy + radius * Math.sin(angle)];
  }
  const dip = cubicBezier(lobeIn, -lobeDepths[dot], lobeOut, 1)(span);
  const radius = restRadius[dot] + dip * (ringRadius - restRadius[dot]);
  const angle = (restAngle[dot] + swingEase(span) * angleGap[dot]) * deg;
  return [cx + radius * Math.cos(angle), cy + radius * Math.sin(angle)];
};

// 最後の動き: 共通の回す角度で全点を回し、各点はリングから次の席へ寄せる
const turnEase = cubicBezier(...phiBezier);
const chordEase = cubicBezier(...sConBezier);
const turnAt = (frame, delay) => {
  const local = frame - delay;
  if (local <= windowStart) return 0;
  if (local >= windowEnd) return turntableDeg;
  return turntableDeg * turnEase((local - windowStart) / (windowEnd - windowStart));
};
const chordAt = (frame, delay) => {
  const local = frame - delay;
  if (local <= windowStart) return 0;
  if (local >= windowEnd) return 1;
  return chordEase((local - windowStart) / (windowEnd - windowStart));
};

function dotsAt(frame) { // フレーム番号 → 各点の置き場所。動きを選び、点ごとに読む
  const f = wrap(frame, periodFrames);
  return restPositions.map((_, dot) => {
    const slot = restToRing[dot];
    const delay = delaysPerSlot[slot];
    if (f <= lastArrival) { const [x, y] = expand(f, dot); return { cx: x, cy: y, r: dotRadius }; }
    if (f - delay < windowStart) return { cx: slotPoint[slot][0], cy: slotPoint[slot][1], r: dotRadius }; // 中ほどの動き: リングで静止
    const chord = chordAt(f, delay);
    const rlx = slotPoint[slot][0] - cx;
    const rly = slotPoint[slot][1] - cy;
    const lx = rlx + chord * (destLocal[dot][0] - rlx);
    const ly = rly + chord * (destLocal[dot][1] - rly);
    const turn = turnAt(f, delay) * deg;
    return { cx: cx + lx * Math.cos(turn) - ly * Math.sin(turn), cy: cy + lx * Math.sin(turn) + ly * Math.cos(turn), r: dotRadius };
  });
}

const wrap = (value, span) => ((value % span) + span) % span;

// 着地の入り口速度 — 落ちカーブの出口の傾きから出す(あとのゆれの出だしになる)
const landVelocity = () => {
  const [, , c2x, c2y] = fallBezier;
  const slope = 1 - c2x > 0 ? (1 - c2y) / (1 - c2x) : 0;
  return slope * (restCy - cyApex) / fallDur;
};

// 高さ cy(tau): 休み → 上り → 頂点 → 下り、着地後はゆれておさまる
const cyAt = (tau) => {
  const amp = restCy - cyApex;
  if (tau < riseDur) return restCy - amp * cubicBezier(...riseBezier)(tau / riseDur);
  const landTau = riseDur + fallDur;
  if (tau < landTau) return cyApex + amp * cubicBezier(...fallBezier)((tau - riseDur) / fallDur);
  const t = tau - landTau;
  const v = landVelocity();
  return restCy + (v / settleOmega) * Math.exp(-settleLambda * t) * Math.sin(settleOmega * t);
};

// 速度 vy(tau): 同じカーブの傾き。伸び縮みはこれを読む
const vyAt = (tau) => {
  const amp = restCy - cyApex;
  if (tau < riseDur) return (-amp / riseDur) * cubicBezierSlope(...riseBezier)(tau / riseDur);
  const landTau = riseDur + fallDur;
  if (tau < landTau) return (amp / fallDur) * cubicBezierSlope(...fallBezier)((tau - riseDur) / fallDur);
  const t = tau - landTau;
  const v = landVelocity();
  const e = Math.exp(-settleLambda * t);
  return (v / settleOmega) * e * (settleOmega * Math.cos(settleOmega * t) - settleLambda * Math.sin(settleOmega * t));
};

// しずく: 分離フレームを起点に、半径は等比でしぼみ、cy は行き先へ寄っていく
const satelliteAt = (sourceFrame, cx) => {
  const half = periodFrames / 2;
  const age = wrap(sourceFrame - separationFrame + half, periodFrames) - half;
  if (age < -preSeparationFrames || age >= lifeFrames) return null;
  return {
    cx,
    cy: cyAsymptote + (cyAnchor - cyAsymptote) * cyRatio ** age,
    r: rAnchor * rDecay ** age,
  };
};

function dotsAt(frame) { // フレーム番号 → 各カプセルの状態。同じ動きを時間ずらしで再生する
  return Array.from({ length: dotCount }, (_, i) => {
    const sourceFrame = wrap(frame - i * staggerFrames, periodFrames); // ← 時間遅延の正体
    const tau = wrap(sourceFrame - tLift, periodFrames);
    const scaleY = 1 + stretchK * Math.abs(vyAt(tau));
    const cx = dotCx0 + i * dotSpacing;
    return {
      cx,
      cy: cyAt(tau),
      width: sizeBasePx,
      height: sizeBasePx * scaleY,
      satellite: satelliteAt(sourceFrame, cx),
    };
  });
}

const wrap = (value, span) => ((value % span) + span) % span;

// フレーム番号 → いま何割すすんだか(0 から 1)。ひと送りのあいだ前へ進み、送り切ったら待つ
const progressAt = (frame) => {
  const local = wrap(frame, periodFrames);
  const subcycle = Math.floor(local / subcycleFrames);
  const within = local - subcycle * subcycleFrames;
  return cubicBezier(...easeHandles)(Math.min(within / activeFrames, 1));
};

const slotCount = slotKeys.length;
const dupCount = Math.round(periodFrames / subcycleFrames);

// スロットの大きさ。時間ずらしの複製のうち 1 つだけ、右のひとつが別の値を返す
const valueOf = (slot, dup) => {
  if (dup === overrideDup && slot === overrideSlot) return overrideValue;
  return slot >= 0 && slot < slotCount ? slotKeys[slot] : 0;
};

function dotsAt(frame) { // フレーム番号 → 各スロットの位置と大きさ。1 つの progress が両方を決める
  const subcycle = Math.floor(wrap(frame, periodFrames) / subcycleFrames);
  const progress = progressAt(frame);
  return slotKeys.map((_, slot) => {
    const dup = wrap(subcycle + slot - (slotCount - 1), dupCount);
    return {
      coord: anchor + spacing * (slot - progress),
      value: valueOf(slot, dup) * (1 - progress) + valueOf(slot - 1, dup) * progress,
      slot,
    };
  });
}

const wrap = (frame, span) => ((frame % span) + span) % span;

// パルス本体: ピークから下り、出口の速さが種になって小さく揺れて収まる
const pulseExitSlope = () => {
  const [, , x2, y2] = decayBez;
  return ((1 - y2) / (1 - x2)) * ((0 - peak) / decayZeroTau);
};
const pulseAt = (tau) => {
  const t = wrap(tau, periodFrames);
  let base = 0;
  if (t <= decayZeroTau) base = peak + (0 - peak) * cubicBezier(...decayBez)(t / decayZeroTau);
  else if (t >= attackStartTau) base = peak * cubicBezier(...attackBez)((t - attackStartTau) / (periodFrames - attackStartTau));
  const v = pulseExitSlope();
  const settle = [0, 1].reduce((sum, m) => {
    const d = wrap(t - decayZeroTau, periodFrames) + m * periodFrames;
    return sum + (v * Math.exp(-settleLambda * d) * Math.sin(settleOmega * d)) / settleOmega;
  }, 0);
  return base + settle;
};

const DEG = Math.PI / 180;
const signedDelta = (a, b) => ((((a - b) + 180) % 360) + 360) % 360 - 180;

// フレーム番号 → 内側の点とリングの点の位置
function dotsAt(frame) {
  const f = wrap(frame, periodFrames);
  // 内側の周回体: easing なしの一定速で回る — これが通り過ぎる側
  const orbitDeg = innerStartAngle + innerSpeed * f;
  const ix = cx + orbitRadius * Math.sin(orbitDeg * DEG);
  const iy = cy - orbitRadius * Math.cos(orbitDeg * DEG);

  const ring = restAngles.map((angDeg, k) => {
    // 止まらない時計: 各点は同じパルスを整数クロックぶん遅らせて読む
    const tau = wrap(f - (pulseAnchor + pulseClock * k), periodFrames);
    const rPre = restRadius + pulseAt(tau);
    const ux = Math.sin(angDeg * DEG);
    const uy = -Math.cos(angDeg * DEG);
    const delta = signedDelta(orbitDeg, angDeg);
    // 距離で決まる力(距離はパルス込み = フィードバック): 押し出しとすべり・二乗で弱まる
    const dPre = Math.hypot(ix - (cx + rPre * ux), iy - (cy + rPre * uy));
    const rAct = rPre + (pushStrength * Math.cos(delta * DEG)) / dPre ** 2;
    const dAct = Math.hypot(ix - (cx + rAct * ux), iy - (cy + rAct * uy));
    const slide = (-slideStrength * Math.sin(delta * DEG)) / dAct ** 2;
    const effDeg = angDeg + (slide / rAct) / DEG;
    return { cx: cx + rAct * Math.sin(effDeg * DEG), cy: cy - rAct * Math.cos(effDeg * DEG) };
  });

  return { inner: { cx: ix, cy: iy }, ring };
}

const wrap = (frame, span) => ((frame % span) + span) % span;

// 折り返す時計: ミラーで折り返し、後半は前半を逆にたどる
const clockAt = (frame) => {
  const t = wrap(frame, periodFrames);
  if (t <= mirrorFrame) return t;
  return Math.max(2 * mirrorFrame - t, 0);
};

// チャネルの形: 片道で動く ramp と、山なりに動いて戻る bump
const rampAt = (ch, t) => ch.end * cubicBezier(...ch.ease)((t - ch.t0) / (ch.endF - ch.t0));
const bumpAt = (ch, t) => {
  if (t <= ch.apexF) return ch.base + (ch.apex - ch.base) * cubicBezier(...ch.e1)((t - ch.t0) / (ch.apexF - ch.t0));
  return ch.base + (ch.apex - ch.base) * (1 - cubicBezier(...ch.e2)((t - ch.apexF) / (ch.endF - ch.apexF)));
};

// フレーム番号 → 円の位置
function circlesAt(frame) {
  const t = clockAt(frame);
  const u = rampAt(uChan, t); // 塗りの円の、軸に沿った開き
  const v = bumpAt(vChan, t); // 塗りの円の、横へのふくらみ
  const s = rampAt(sChan, t); // 輪郭の円の開き(u を少し遅れて追う)
  const w = bumpAt(wChan, t); // 輪郭の円の線の太さ

  // ひとつの軸に沿って、符号を変えて置くだけ
  const rad = axisDeg * Math.PI / 180;
  const ax = Math.cos(rad), ay = Math.sin(rad);
  const bx = -Math.sin(rad), by = Math.cos(rad);
  const place = (du, dv, r) => ({ cx: cx + ax * du + bx * dv, cy: cy + ay * du + by * dv, r });

  return {
    // 塗りの円: 共有する (u, v) の符号配置
    quad: [place(u, v, quadRadius), place(-u, -v, quadRadius), place(u, -v, quadRadius), place(-u, v, quadRadius)],
    // 輪郭の円: 軸上の (±s, 0)
    axial: [place(s, 0, axialRadius), place(-s, 0, axialRadius)],
    bandWidth: w,
  };
}

// フレーム番号をループの中の位置へ折り返す
const wrap = (frame, span) => ((frame % span) + span) % span;

// 最初に一度だけ: 傾けたリングの向きと、親まわり・子まわりの回る速さ
const n0 = tiltedUnit(axis, tiltDeg, tiltAzimuthDeg);
const parentPerFrame = 360 * parentTurns / periodFrames;
const spinPerFrame = 360 * spinTurns / periodFrames;

// フレーム番号 → 各円の画面での位置と大きさ
const dotsAt = (frame) => {
  const t = wrap(frame, periodFrames);
  // 子: 円がリングの向きのまわりをめぐる
  const ring = ringPoints3d(n0, spinPhase0 + spinPerFrame * t, ringRadius, count);
  // 親: リングごと画面の軸のまわりに回る
  const rot = rotationAboutAxis(axis, parentPerFrame * t);
  return ring.map((p, i) => {
    const spun = applyMat3(rot, p);
    const z = spun[2] / ringRadius;
    const m = 1 + depthK * z; // ひとつの遠近の倍率を位置にも大きさにも同じだけ
    const dark = i % 2 === 0;
    return {
      cx: center[0] + spun[0] * m,
      cy: center[1] + spun[1] * m,
      r: (dark ? darkRadius : lightRadius) * m,
      z,
      dark,
    };
  });
};

// フレーム番号をループの中の位置へ折り返す
const wrap = (frame, span) => ((frame % span) + span) % span;

// 往復の波: ピークまで上がって戻り、そのあと長い休み
const riseSpan = peakFrame - riseStart;
const fallSpan = fallEnd - peakFrame;
const restLo = fallEnd;
const restHi = riseStart + periodFrames;

const phaseAt = (local) => {
  if (local >= restLo && local <= restHi) return null;
  if (local <= peakFrame) {
    const unwrapped = local >= restHi ? local - periodFrames : local;
    return { p: (unwrapped - riseStart) / riseSpan, rising: true };
  }
  return { p: (local - peakFrame) / fallSpan, rising: false };
};

const scaleAt = (local) => {
  const ph = phaseAt(local);
  if (!ph) return restScale;
  const amp = 1 - restScale;
  if (ph.rising) return restScale + amp * cubicBezier(...scaleRise)(ph.p);
  return restScale + amp * (1 - cubicBezier(...scaleFall)(ph.p));
};

const thetaAt = (local) => {
  const ph = phaseAt(local);
  if (!ph) return restTheta;
  if (ph.rising) return 180 * cubicBezier(...thetaRise)(ph.p);
  return 180 * (1 - cubicBezier(...thetaFall)(ph.p));
};

// 縁の点を傾いた軸で回し、奥行きを捨てて画面へ落とす
const projectAboutTiltedAxis = (x, y, z, axisCos, axisSin, th) => {
  const c = Math.cos(th);
  const s = Math.sin(th);
  const t = 1 - c;
  const px = (t * axisCos * axisCos + c) * x + t * axisCos * axisSin * y + s * axisSin * z;
  const py = t * axisCos * axisSin * x + (t * axisSin * axisSin + c) * y + -s * axisCos * z;
  return [px, py];
};

const axisTilt = axisTiltDeg * Math.PI / 180;

// フレーム番号 → 円盤の輪郭
const discAt = (frame) => {
  const local = wrap(frame, periodFrames);
  const scale = scaleAt(local);
  const thetaDeg = thetaAt(local);
  const th = thetaDeg * Math.PI / 180;
  const r = peakOuterR * scale;
  const onFall = local >= fallStart && local <= fallAxisEnd;
  const axisCos = Math.cos(axisTilt);
  const axisSin = Math.sin(axisTilt) * (onFall ? -1 : 1);

  // 両側のリムを点群に投影する
  const rim = [thicknessRatio * r, -thicknessRatio * r].flatMap((fz) =>
    Array.from({ length: rimCount }, (_, i) => {
      const a = 2 * Math.PI * i / rimCount;
      const [x, y] = projectAboutTiltedAxis(r * Math.cos(a), r * Math.sin(a), fz, axisCos, axisSin, th);
      return [x + pivot[0], y + pivot[1]];
    }),
  );
  // 輪郭はその点群の凸包
  const outline = convexHull(rim);

  const edgeOnness = Math.abs(Math.sin(th));
  return { outline, scale, thetaDeg, edgeOnness };
};
